package android.graphics;import java.io.*;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;public class BitmapFactory {public static class Options {public boolean inJustDecodeBounds;public int outWidth,outHeight,inSampleSize=1;}public static Bitmap decodeByteArray(byte[] b,int offset,int length){return decodeByteArray(b,offset,length,new Options());}public static Bitmap decodeByteArray(byte[] b,int offset,int length,Options o){try{BufferedImage image=ImageIO.read(new ByteArrayInputStream(b,offset,length));if(image==null)return null;o.outWidth=image.getWidth();o.outHeight=image.getHeight();return o.inJustDecodeBounds?null:new Bitmap(image);}catch(Exception e){return null;}}}